"""Only fresh private paths; no worker, GC/delete, fallback or user data."""
import ctypes
import errno
import hashlib
import json
import os
from pathlib import Path
import socket

from orze.engine.gc_tree import rename_no_replace

libc = ctypes.CDLL(None, use_errno=True)
rename = libc.renameat2
rename.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint)
rename.restype = ctypes.c_int
report = []
for root in map(Path, ('/hot-data/fsx/workspace/erik/orze-fs-probe.8i6r57',
                      '/tmp/orze-fs-probe.7pmzPJ')):
    item = {'root': str(root), 'device': root.stat().st_dev, 'renames': [], 'sockets': []}
    for directory in (False, True):
        for collision in (False, True):
            case = root / ('directory' if directory else 'file') / str(collision)
            case.mkdir(parents=True)
            source, target = case / 'source', case / 'target'
            if directory:
                source.mkdir()
                if collision:
                    target.mkdir()
            else:
                source.write_bytes(b'private-source')
                if collision:
                    target.write_bytes(b'private-target')
            descriptor = os.open(case, os.O_RDONLY | os.O_DIRECTORY)
            try:
                ctypes.set_errno(0)
                result = rename(descriptor, b'source', descriptor, b'target', 1)
                error = ctypes.get_errno()
            finally:
                os.close(descriptor)
            item['renames'].append({'directory': directory, 'collision': collision,
                'returncode': result, 'errno': error, 'errno_name': errno.errorcode.get(error),
                'source_exists': source.exists(), 'target_exists': target.exists(),
                'unchanged_existing_target': not collision or directory or target.read_bytes() == b'private-target'})
    source, target = root / 'public-source', root / 'public-target'
    source.mkdir()
    try:
        rename_no_replace(source, target)
    except Exception as exc:
        item['actual_product_rename'] = {'type': type(exc).__name__, 'reason': str(exc)}
    else:
        item['actual_product_rename'] = {'success': True}
    long = root / ('long-' + 'x' * 100)
    long.mkdir()
    for parent in (root, long):
        endpoint = parent / 'channel.sock'
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as channel:
            try:
                channel.bind(str(endpoint))
            except OSError as exc:
                outcome = {'type': type(exc).__name__, 'reason': str(exc), 'errno': exc.errno}
            else:
                outcome = {'success': True}
        item['sockets'].append({'path': str(endpoint), 'utf8_bytes': len(os.fsencode(endpoint)), **outcome})
    report.append(item)
print(json.dumps({'probe_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                  'results': report, 'left_private_fixture_paths': True}, sort_keys=True))

